recs.append(R(7106172,"چاکلیٹ موس رسبھریوں کے ساتھ","ہلکا اور پھولا ہوا موس جو پھلوں کے ساتھ مل کر ایک مزیدار میٹھا بناتا ہے۔","6","102 گرام",
["100 گرام چاکلیٹ (85% کوکو ٹھوس اجزاء)","4 ڈھیر والے چائے کے چمچ دانے دار چینی سے پاک سویٹنر (20 گرام)","200 ملی لیٹر چکنائی سے پاک یونانی دہی","2 انڈوں کی سفیدی","250 گرام رسبھریاں"],
["پیالے کو آہستہ آہستہ ابلتے پانی کے سوس پین کے اوپر رکھیں۔ چاکلیٹ کو چوکور ٹکڑوں میں توڑ کر پیالے میں ڈالیں، اس بات کو یقینی بنائیں کہ پیالہ پانی کو چھو نہ رہا ہو۔ چینی ڈالیں اور نرمی سے ہلائیں یہاں تک کہ چاکلیٹ پگھل جائے اور چینی گھل جائے۔","اس کے بعد آدھا یونانی دہی پیالے میں ڈالیں، اچھی طرح ملائیں، پھر سوس پین سے اتار لیں۔ باقی یونانی دہی ملا دیں۔","انڈوں کی سفیدی دوسرے پیالے میں ڈالیں، اور اس وقت تک پھینٹیں جب تک وہ سخت اور پھولی ہوئی نہ ہو جائیں۔ پھر انہیں احتیاط سے چاکلیٹ میں ملا دیں۔","آمیزہ 6 چھوٹے گلاسوں یا ایسپریسو کپوں میں چمچ سے ڈالیں اور کم از کم 30 منٹ فریج میں رکھیں۔","پیش کرنے سے ذرا پہلے ہر موس کو ایک رسبھری سے سجائیں، اور باقی رسبھریاں ساتھ پیش کریں۔ پیش کرتے وقت آپ مزید پھل بھی ڈال سکتے ہیں، جیسے بلیو بیریز، سنگترے کی پھانکیں اور تازہ انجیر کے قتلے، ساتھ تازہ پودینے کی چند ٹہنیاں۔"],
["موس کا ایک پیالہ پیش کریں اور اس کے گرد کاک ٹیل اسٹک پر لگے پھلوں کے ٹکڑے رکھیں تاکہ چاکلیٹ فونڈو بن جائے۔","اسٹرابیریاں، سیب، ناشپاتی، کیلا اور کمکوات سب ڈبونے کے لیے بہترین ہیں۔ یا چینی سے پاک مارش میلو آزمائیں۔","اپنے موس کو ہلکا چاکلیٹ ذائقہ دینے کے لیے پگھلتی ہوئی چاکلیٹ میں ایک سنگترے کا باریک کدوکش کیا ہوا چھلکا ڈالیں یا اضافی ذائقے کے لیے ایک چائے کا چمچ بادام کا ایکسٹریکٹ ڈالیں۔",FVH(0)],[]))
